// best opp path sum from pos 2, avoiding occupied mask (bits). steps 1..4, until stuck.
long long oppbest;
int occ;
long long oppdp(int p){
  // returns max sum from p (opp), moving until stuck
  long long best=-1e18; bool any=false;
  for(int d=1;d<=4;d++){int c=p+d; if(c<=n && !(occ>>c&1)){ any=true; long long v=a[c]+oppdp(c); best=max(best,v);} }
  if(!any) return 0;
  return best;
}
long long commitBest;
void enumMe(int p,long long sum,int mymask){
  // me path so far ends at p; continue until stuck
  bool any=false;
  for(int d=1;d<=4;d++){int c=p+d; if(c<=n && !(mymask>>c&1) && c!=2){ any=true; enumMe(c,sum+a[c],mymask|(1<<c)); } }
  if(!any){
    // evaluate
    occ = mymask | (1<<2);
    long long ob=oppdp(2);
    commitBest=max(commitBest, sum-ob);
  }
}
