#include <bits/stdc++.h>
using namespace std;
int n; long long a[60];
struct Key{int p1,p2; unsigned long long mask; int lo; bool operator==(const Key&o)const{return p1==o.p1&&p2==o.p2&&mask==o.mask&&lo==o.lo;}};
struct H{size_t operator()(const Key&k)const{return ((size_t)k.p1*1000003 + k.p2)*1000003 + (size_t)(k.mask*1099511628211ULL) + k.lo;}};
unordered_map<Key,long long,H> memo[2];
long long cnt=0;
bool isocc(const Key&k,int c){ if(c<k.lo) return true; /* behind: treat as irrelevant but for move validity we only consider cells >= lo */ return (k.mask>>(c-k.lo))&1ULL; }
long long solve(int p1,int p2,unsigned long long mask,int lo,int turn){
  Key k{p1,p2,mask,lo};
  auto it=memo[turn].find(k); if(it!=memo[turn].end()) return it->second;
  cnt++;
  int hi=max(p1,p2);
  // can move helpers
  auto can=[&](int p)->bool{
    for(int d=1;d<=4;d++){int c=p+d; if(c<=n){ if(c>=lo){ if(!((mask>>(c-lo))&1ULL)) return true;} else return true; } }
    return false;
  };
  bool can0=can(p1),can1=can(p2);
  if(!can0&&!can1) return memo[turn][k]=0;
  long long res;
  if(turn==0){
    if(!can0) res=solve(p1,p2,mask,lo,1);
    else{res=LLONG_MIN;
      for(int d=1;d<=4;d++){int c=p1+d; if(c>n)break; bool fr; if(c>=lo) fr=!((mask>>(c-lo))&1ULL); else fr=true; if(!fr)continue;
        // new state: occupied cell c
        int nlo=min(c,p2), nhi=max(c,p2);
        unsigned long long nm=0;
        // set all occupied cells from old window that fall in [nlo,nhi], plus c
        for(int x=nlo;x<=nhi;x++){
          bool occ=false;
          if(x==c||x==p2) occ=true;
          else if(x>=lo && x<=hi && ((mask>>(x-lo))&1ULL)) occ=true;
          if(occ) nm|=1ULL<<(x-nlo);
        }
        res=max(res,a[c]+solve(c,p2,nm,nlo,1));
      }
    }
  } else {
    if(!can1) res=solve(p1,p2,mask,lo,0);
    else{res=LLONG_MAX;
      for(int d=1;d<=4;d++){int c=p2+d; if(c>n)break; bool fr; if(c>=lo) fr=!((mask>>(c-lo))&1ULL); else fr=true; if(!fr)continue;
        int nlo=min(p1,c), nhi=max(p1,c);
        unsigned long long nm=0;
        for(int x=nlo;x<=nhi;x++){
          bool occ=false;
          if(x==p1||x==c) occ=true;
          else if(x>=lo && x<=hi && ((mask>>(x-lo))&1ULL)) occ=true;
          if(occ) nm|=1ULL<<(x-nlo);
        }
        res=min(res,-a[c]+solve(p1,c,nm,nlo,0));
      }
    }
  }
  return memo[turn][k]=res;
}
