void getBoard(int *arr){ for(int i=3;i<=n;i++)a[i]=arr[i]; memo[0].clear();memo[1].clear(); solve(1,2,(1<<1)|(1<<2),0);
  // reconstruct optimal board marks: me=+1, opp=-1, else 0
  int p1=1,p2=2,mask=(1<<1)|(1<<2),turn=0; for(int i=1;i<=n;i++)sgn[i]=0; sgn[1]=0;sgn[2]=0;
  while(true){
