    for(int d=1;d<=4;d++){int c=p1+d;if(c<=n&&!(mask>>c&1)){can0=true;break;}}
    for(int d=1;d<=4;d++){int c=p2+d;if(c<=n&&!(mask>>c&1)){can1=true;break;}}
    if(!can0&&!can1)break;
    if(turn==0){ if(!can0){turn=1;continue;} long long best=LLONG_MIN;int bc=-1;
      for(int d=1;d<=4;d++){int c=p1+d;if(c<=n&&!(mask>>c&1)){long long v=a[c]+solve(c,p2,mask|(1<<c),1);if(v>best){best=v;bc=c;}}}
      sgn[bc]=1;mask|=1<<bc;p1=bc;turn=1;}
    else{ if(!can1){turn=0;continue;} long long best=LLONG_MAX;int bc=-1;
      for(int d=1;d<=4;d++){int c=p2+d;if(c<=n&&!(mask>>c&1)){long long v=-a[c]+solve(p1,c,mask|(1<<c),0);if(v<best){best=v;bc=c;}}}
